        let body = payload["text"].as_str().unwrap();
        assert!(body.contains("Ask:") && body.contains("From:") && body.contains("Where:"));
        assert!(!payload["blocks"].to_string().contains("litecom_approve"));
        assert_eq!(t.count("approvals"), 1);
    }
