                text: String::new(),
                attachment_ids: vec![],
                action: Some(action),
            },
        )
        .unwrap();
    assert!(
        t.state
            .db()
            .unwrap()
            .claim(&t.worker, &t.agent)
            .unwrap()
            .is_none()
    );
    let slack_p = t
        .state
        .db()
        .unwrap()
        .slack_principal("T1", "U1")
        .unwrap()
        .unwrap();
